let _markdown = "\n\nOverview [#overview]\n\n<FeedbackBlock id=\"fa501894d82a688a\" body=\"Loader plugins can extend loader() to customise its output.\">\n  Loader plugins can extend `loader()` to customise its output.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"b037dec63b42de6c\" body=\"A list of built-in plugins:\">\n  A list of built-in plugins:\n</FeedbackBlock>\n\n<FeedbackBlock\n  id=\"d4b450ca2f5cf382\"\n  body=\"Lucide Icons: use icons from Lucide React (require lucide-react to be installed).import { loader } from 'fumadocs-core/source';\nimport { lucideIconsPlugin } from 'fumadocs-core/source/lucide-icons';\n\nexport const source = loader({\n  // ...\n  plugins: [lucideIconsPlugin()],\n});\"\n>\n  * **Lucide Icons**: use icons from [Lucide React](https://lucide.dev) (require `lucide-react` to be installed).\n\n    ```ts\n    import { loader } from 'fumadocs-core/source';\n    import { lucideIconsPlugin } from 'fumadocs-core/source/lucide-icons';\n\n    export const source = loader({\n      // ...\n      plugins: [lucideIconsPlugin()],\n    });\n    ```\n</FeedbackBlock>\n\nCreating Plugins [#creating-plugins]\n\n<FeedbackBlock id=\"d579f21167434ead\" body=\"Each plugin is an object:\">\n  Each plugin is an object:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Strictly Typed\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Strictly Typed\">\n      Strictly Typed\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Simple\">\n      Simple\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Strictly Typed\">\n    ```ts\n    import { loader } from 'fumadocs-core/source';\n\n    export const source = loader({\n      plugins: ({ typedPlugin }) => [\n        typedPlugin({\n          // plugin config\n        }),\n      ],\n    });\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Simple\">\n    ```ts\n    import { loader, type LoaderPlugin } from 'fumadocs-core/source';\n\n    export const source = loader({\n      plugins: [myPlugin()],\n    });\n\n    function myPlugin(): LoaderPlugin {\n      return {\n        // plugin config\n      };\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<Callout title=\"Good to know\">\n  `typedPlugin` enforces a more accurate type for plugin, including custom properties from your content source.\n\n  But to make the plugin reusable (across different loaders), use the `LoaderPlugin` type instead.\n</Callout>\n\nStorage [#storage]\n\n<FeedbackBlock id=\"bc3e39a1aee04cfd\" body=\"During the process, your input source files will be parsed and form a virtual storage in memory.\">\n  During the process, your input source files will be parsed and form a virtual storage in memory.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"04954ddbc2865b5d\" body=\"To perform virtual file-system operations before processing, you can hook transformStorage.\">\n  To perform virtual file-system operations before processing, you can hook `transformStorage`.\n</FeedbackBlock>\n\n```ts\nimport { loader } from 'fumadocs-core/source';\n\nexport const source = loader({\n  plugins: ({ typedPlugin }) => [\n    typedPlugin({\n      transformStorage({ storage }) {\n        storage.read('my/path');\n      },\n    }),\n  ],\n});\n```\n\nPage Tree [#page-tree]\n\n<FeedbackBlock id=\"15110d2b2db6faac\" body=\"The page tree is generated from your file system, some unnecessary information (e.g. unused frontmatter properties) will be filtered.\">\n  The page tree is generated from your file system, some unnecessary information (e.g. unused frontmatter properties) will be filtered.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"d0aac255c0b0474c\" body=\"You can customise it using the transformPageTree, such as attaching custom properties to nodes, or customising the display name of pages.\">\n  You can customise it using the `transformPageTree`, such as attaching custom properties to nodes, or customising the display name of pages.\n</FeedbackBlock>\n\n```tsx\nimport { loader } from 'fumadocs-core/source';\n\nexport const source = loader({\n  plugins: ({ typedPlugin }) => [\n    typedPlugin({\n      transformPageTree: {\n        file(node, file) {\n          // access the original (unfiltered) file data\n          if (file) console.log(this.storage.read(file));\n\n          // modify nodes\n          node.name = <>Some JSX Nodes here</>;\n          return node;\n        },\n      },\n    }),\n  ],\n});\n```\n";
